package main

import (
	"context"
	_ "embed"
	"errors"
	"fmt"
	"math/big"
	"strings"
	"time"

	"github.com/ethereum/go-ethereum"
	"github.com/ethereum/go-ethereum/accounts/abi"
	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/core/types"
	"github.com/ethereum/go-ethereum/ethclient"
)

// escrow_abi.json is generated by `npm run compile` in contracts/.
//
//go:embed escrow_abi.json
var escrowABIJSON []byte

var (
	errTxPending  = errors.New("transaction not confirmed yet")
	errTxReverted = errors.New("transaction reverted")
)

// ChainInfo is what the frontend needs to talk to the deployed contract.
type ChainInfo struct {
	ChainID int64  `json:"chainId"`
	Escrow  string `json:"escrow"`
	USDC    string `json:"usdc"`
}

// ChainEvent is one decoded JobEscrow event from a confirmed transaction.
type ChainEvent struct {
	Name      string
	Args      map[string]any
	BlockTime time.Time
}

// Verifier turns a transaction hash into the escrow events it emitted.
// The real implementation reads a node; tests substitute a fake.
type Verifier interface {
	Events(ctx context.Context, txHash string) ([]ChainEvent, error)
}

type Chain struct {
	rpc      *ethclient.Client
	contract common.Address
	abi      abi.ABI
}

// newChain connects to the node, checks it is on the expected chain and reads the escrow's token address.
func newChain(ctx context.Context, rpcURL, escrow string, chainID int64) (*Chain, *ChainInfo, error) {
	if !common.IsHexAddress(escrow) {
		return nil, nil, errors.New("ESCROW_ADDRESS is not a valid address")
	}
	parsed, err := abi.JSON(strings.NewReader(string(escrowABIJSON)))
	if err != nil {
		return nil, nil, fmt.Errorf("escrow ABI: %w", err)
	}
	rpc, err := ethclient.DialContext(ctx, rpcURL)
	if err != nil {
		return nil, nil, fmt.Errorf("RPC_URL: %w", err)
	}
	got, err := rpc.ChainID(ctx)
	if err != nil {
		return nil, nil, fmt.Errorf("cannot reach RPC node: %w", err)
	}
	if chainID != 0 && got.Int64() != chainID {
		return nil, nil, fmt.Errorf("RPC node is on chain %d but CHAIN_ID=%d", got.Int64(), chainID)
	}
	c := &Chain{rpc: rpc, contract: common.HexToAddress(escrow), abi: parsed}

	data, err := parsed.Pack("token")
	if err != nil {
		return nil, nil, err
	}
	out, err := rpc.CallContract(ctx, ethereum.CallMsg{To: &c.contract, Data: data}, nil)
	if err != nil || len(out) < 32 {
		return nil, nil, fmt.Errorf("no JobEscrow contract at %s on chain %d", escrow, got.Int64())
	}
	token := common.BytesToAddress(out[12:32])
	return c, &ChainInfo{ChainID: got.Int64(), Escrow: c.contract.Hex(), USDC: token.Hex()}, nil
}

func (c *Chain) Events(ctx context.Context, txHash string) ([]ChainEvent, error) {
	h := common.HexToHash(txHash)
	var rc *types.Receipt
	var err error
	// A node may lag a block or two behind the wallet that just confirmed the transaction.
	for i := 0; i < 15; i++ {
		rc, err = c.rpc.TransactionReceipt(ctx, h)
		if err == nil {
			break
		}
		if !errors.Is(err, ethereum.NotFound) {
			return nil, err
		}
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(time.Second):
		}
	}
	if rc == nil {
		return nil, errTxPending
	}
	if rc.Status != types.ReceiptStatusSuccessful {
		return nil, errTxReverted
	}
	hdr, err := c.rpc.HeaderByNumber(ctx, rc.BlockNumber)
	if err != nil {
		return nil, err
	}
	evs, err := parseLogs(c.abi, c.contract, rc.Logs)
	if err != nil {
		return nil, err
	}
	for i := range evs {
		evs[i].BlockTime = time.Unix(int64(hdr.Time), 0).UTC()
	}
	return evs, nil
}

// parseLogs decodes the escrow contract's events out of a receipt's logs, ignoring everything else.
func parseLogs(a abi.ABI, contract common.Address, logs []*types.Log) ([]ChainEvent, error) {
	var out []ChainEvent
	for _, l := range logs {
		if l.Address != contract || len(l.Topics) == 0 {
			continue
		}
		ev, err := a.EventByID(l.Topics[0])
		if err != nil {
			continue
		}
		args := map[string]any{}
		var indexed abi.Arguments
		for _, in := range ev.Inputs {
			if in.Indexed {
				indexed = append(indexed, in)
			}
		}
		if err := abi.ParseTopicsIntoMap(args, indexed, l.Topics[1:]); err != nil {
			return nil, fmt.Errorf("%s topics: %w", ev.Name, err)
		}
		if len(ev.Inputs.NonIndexed()) > 0 {
			if err := ev.Inputs.UnpackIntoMap(args, l.Data); err != nil {
				return nil, fmt.Errorf("%s data: %w", ev.Name, err)
			}
		}
		out = append(out, ChainEvent{Name: ev.Name, Args: args})
	}
	return out, nil
}

// ---- typed accessors for decoded event arguments ----

func (e ChainEvent) bigInt(name string) *big.Int {
	if v, ok := e.Args[name].(*big.Int); ok {
		return v
	}
	return nil
}

func (e ChainEvent) uint(name string) (uint64, bool) {
	if v := e.bigInt(name); v != nil && v.IsUint64() {
		return v.Uint64(), true
	}
	return 0, false
}

func (e ChainEvent) address(name string) common.Address {
	a, _ := e.Args[name].(common.Address)
	return a
}

func (e ChainEvent) bps(name string) (int, bool) {
	switch v := e.Args[name].(type) {
	case uint16:
		return int(v), true
	case *big.Int:
		return int(v.Int64()), true
	}
	return 0, false
}

func (e ChainEvent) bytes32(name string) ([32]byte, bool) {
	v, ok := e.Args[name].([32]byte)
	return v, ok
}
